-- 武汉大学招生问答智能体：建表脚本（PostgreSQL）
-- 由 admission_agent 库结构导出，可直接在空库中执行

CREATE SCHEMA IF NOT EXISTS public;

DROP TABLE IF EXISTS public.hubei_score_ranks CASCADE;
CREATE TABLE public.hubei_score_ranks (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "year" character varying(4) NOT NULL,
    "province" character varying(10) DEFAULT '湖北'::character varying NOT NULL,
    "subject_category" character varying(20) NOT NULL,
    "category_norm" character varying(10),
    "score" integer NOT NULL,
    "count_this_segment" integer,
    "cumulative_count" integer,
    "remark" character varying(200),
    "source_sheet" character varying(50),
    "created_at" timestamp without time zone DEFAULT now() NOT NULL
);
CREATE UNIQUE INDEX hubei_score_ranks_pkey ON public.hubei_score_ranks USING btree (id);
CREATE INDEX idx_score_ranks_year_cat ON public.hubei_score_ranks USING btree (year, category_norm, score);
CREATE UNIQUE INDEX uq_score_rank ON public.hubei_score_ranks USING btree (year, subject_category, score);

DROP TABLE IF EXISTS public.hubei_major_admissions CASCADE;
CREATE TABLE public.hubei_major_admissions (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "year" character varying(4) NOT NULL,
    "province" character varying(10) DEFAULT '湖北'::character varying NOT NULL,
    "admission_category" character varying(30),
    "subject_type" character varying(20),
    "major_group" character varying(20),
    "major_name" character varying(100) NOT NULL,
    "plan_count" integer,
    "first_choice_subject" character varying(30),
    "batch" character varying(30),
    "min_score" integer,
    "min_rank" integer,
    "created_at" timestamp without time zone DEFAULT now() NOT NULL
);
CREATE UNIQUE INDEX hubei_major_admissions_pkey ON public.hubei_major_admissions USING btree (id);
CREATE INDEX idx_major_year_major ON public.hubei_major_admissions USING btree (year, major_name);
CREATE UNIQUE INDEX uq_major_adm ON public.hubei_major_admissions USING btree (year, admission_category, subject_type, COALESCE(major_group, ''::character varying), major_name, COALESCE(batch, ''::character varying));

DROP TABLE IF EXISTS public.whu_group_admissions CASCADE;
CREATE TABLE public.whu_group_admissions (
    "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "year" character varying,
    "subject_type" character varying,
    "major_group" character varying,
    "batch" character varying,
    "category" character varying,
    "min_score" integer,
    "min_rank" integer,
    "subject_req" character varying,
    "data_caliber" character varying,
    "source_status" character varying,
    "note" text,
    "category_norm" character varying(8)
);
CREATE INDEX ix_wga_cat ON public.whu_group_admissions USING btree (category);
CREATE INDEX ix_wga_group ON public.whu_group_admissions USING btree (year, category_norm, major_group);
CREATE INDEX ix_wga_norm ON public.whu_group_admissions USING btree (year, category_norm);
CREATE INDEX ix_wga_y_s ON public.whu_group_admissions USING btree (year, subject_type);
CREATE UNIQUE INDEX uq_wga ON public.whu_group_admissions USING btree (year, subject_type, major_group, category, COALESCE(batch, ''::character varying));
CREATE UNIQUE INDEX whu_group_admissions_pkey ON public.whu_group_admissions USING btree (id);

DROP TABLE IF EXISTS public.whu_major_records CASCADE;
CREATE TABLE public.whu_major_records (
    "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "year" character varying,
    "subject_type" character varying,
    "category" character varying,
    "major_name" character varying,
    "min_score" integer,
    "min_rank" integer,
    "max_score" integer,
    "avg_score" numeric,
    "enroll_count" integer,
    "major_group" character varying,
    "source_status" character varying,
    "note" text,
    "category_norm" character varying(8)
);
CREATE INDEX ix_wmr_cat ON public.whu_major_records USING btree (category);
CREATE INDEX ix_wmr_cat2 ON public.whu_major_records USING btree (year, category_norm, category);
CREATE INDEX ix_wmr_group ON public.whu_major_records USING btree (year, category_norm, major_group);
CREATE INDEX ix_wmr_major ON public.whu_major_records USING btree (major_name);
CREATE INDEX ix_wmr_norm ON public.whu_major_records USING btree (year, category_norm);
CREATE INDEX ix_wmr_y_s ON public.whu_major_records USING btree (year, subject_type);
CREATE UNIQUE INDEX uq_wmr ON public.whu_major_records USING btree (year, subject_type, category, major_name, COALESCE(major_group, ''::character varying));
CREATE UNIQUE INDEX whu_major_records_pkey ON public.whu_major_records USING btree (id);

DROP TABLE IF EXISTS public.whu_school_summary CASCADE;
CREATE TABLE public.whu_school_summary (
    "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "year" character varying,
    "subject_type" character varying,
    "category" character varying,
    "major_group" character varying,
    "min_score" integer,
    "min_rank" integer,
    "caliber" character varying,
    "source_status" character varying,
    "note" text,
    "category_norm" character varying(8)
);
CREATE INDEX ix_wss_norm ON public.whu_school_summary USING btree (year, category_norm);
CREATE INDEX ix_wss_y_s ON public.whu_school_summary USING btree (year, subject_type);
CREATE UNIQUE INDEX whu_school_summary_pkey ON public.whu_school_summary USING btree (id);

DROP TABLE IF EXISTS public.whu_data_coverage CASCADE;
CREATE TABLE public.whu_data_coverage (
    "year" character varying NOT NULL,
    "major_records" integer,
    "major_with_rank" integer,
    "group_records" integer,
    "group_with_rank" integer,
    "gap_note" text
);
CREATE UNIQUE INDEX whu_data_coverage_pkey ON public.whu_data_coverage USING btree (year);
